מה ידפיס הקוד? (כמו שאלה 1 במבחן ותרגילי הכיתה, עם ערך אחר ושדה של 3 ביטים)

```c
#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint8_t r = 0xB6;                                   /* 1011 0110 */
    uint8_t a = r ^ 0x0F;                               /* toggle the low nibble */
    uint8_t b = r & (uint8_t)~(1U << 2);                /* clear bit 2 */
    uint8_t c = (r >> 4) & 0x3;                         /* bits 4-5 */
    uint8_t d = (r & (uint8_t)~(0x7 << 3)) | (5 << 3);  /* field bits 3-5 = 5 */
    printf("0x%02X 0x%02X %u 0x%02X\n", a, b, c, d);
    return 0;
}
```

כמו תרגיל הכלב מהכיתה, עם חלוקה אחרת: ביטים 0-1 צבע (0-3), ביט 2 ישן, ביטים 3-7 משקל (0-31). השלם את המסכות ואת שתי הפונקציות, ומה ידפיס `main`?

```c
#include <stdio.h>
#include <stdint.h>

#define COLOR_BITS   2
#define SLEEP_BIT    2
#define WEIGHT_START 3
#define WEIGHT_BITS  5
#define COLOR_MASK   ((1 << COLOR_BITS) - 1)                          /* 0x03 */
#define SLEEP_MASK   (1 << SLEEP_BIT)                                 /* 0x04 */
#define MAX_WEIGHT   ((1 << WEIGHT_BITS) - 1)                         /* 31 */
#define WEIGHT_MASK  (MAX_WEIGHT << WEIGHT_START)                     /* 0xF8 */

int cat_get_weight(const uint8_t *cat) {
    if (!cat)
        return -1;
    return (*cat & WEIGHT_MASK) >> WEIGHT_START;
}

int cat_set_color(uint8_t *cat, int color) {
    if (!cat || color < 0 || color > COLOR_MASK)
        return -1;
    *cat = (*cat & (uint8_t)~COLOR_MASK) | (uint8_t)color;
    return 0;
}

int main(void) {
    uint8_t cat = 0x5D;                  /* 0101 1101 */
    printf("weight=%d color=%d sleeping=%d\n", cat_get_weight(&cat), cat & COLOR_MASK, (cat & SLEEP_MASK) != 0);
    int rc = cat_set_color(&cat, 2);
    printf("rc=%d cat=0x%02X\n", rc, cat);
    printf("rc=%d cat=0x%02X\n", cat_set_color(&cat, 4), cat);
    return 0;
}
```

כפתור מחובר בין GPIO 4 לאדמה:
```cpp
const int BTN = 4, LED = 2;
int count = 0, last = HIGH;

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int now = digitalRead(BTN);
  if (last == HIGH && now == LOW) {
    count++;
    digitalWrite(LED, count % 2);
    Serial.println(count);
  }
  last = now;
}
```
